-- The tables of a chess-study-manager database that the migration reads (structure only), for tests/test_csm.py.
CREATE TABLE "sources_book" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(300) NOT NULL, "authors" varchar(300) NOT NULL, "isbn" varchar(20) NOT NULL, "year" smallint unsigned NULL CHECK ("year" >= 0), "publisher" varchar(200) NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "sources_website" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "base_url" varchar(200) NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "positions_player" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL, "aliases" text NOT NULL CHECK ((JSON_VALID("aliases") OR "aliases" IS NULL)), "role" varchar(10) NOT NULL, "title" varchar(8) NOT NULL, "federation" varchar(3) NOT NULL, "fide_id" varchar(12) NOT NULL, "born" smallint unsigned NULL CHECK ("born" >= 0), "notes" text NOT NULL, "keys" text NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "positions_game" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "source_type" varchar(10) NOT NULL, "source_page" varchar(40) NOT NULL, "source_ref" varchar(500) NOT NULL, "source_notes" text NOT NULL, "event" varchar(200) NOT NULL, "site" varchar(200) NOT NULL, "date" varchar(20) NOT NULL, "round" varchar(20) NOT NULL, "white" varchar(120) NOT NULL, "black" varchar(120) NOT NULL, "white_elo" varchar(10) NOT NULL, "black_elo" varchar(10) NOT NULL, "result" varchar(10) NOT NULL, "eco" varchar(10) NOT NULL, "annotator" varchar(120) NOT NULL, "start_fen" varchar(100) NOT NULL, "extra_headers" text NOT NULL CHECK ((JSON_VALID("extra_headers") OR "extra_headers" IS NULL)), "pgn_original" text NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "book_id" bigint NULL REFERENCES "sources_book" ("id") DEFERRABLE INITIALLY DEFERRED, "website_id" bigint NULL REFERENCES "sources_website" ("id") DEFERRABLE INITIALLY DEFERRED, "deleted_at" datetime NULL, "black_player_id" bigint NULL REFERENCES "positions_player" ("id") DEFERRABLE INITIALLY DEFERRED, "white_player_id" bigint NULL REFERENCES "positions_player" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "positions_position" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "source_type" varchar(10) NOT NULL, "source_page" varchar(40) NOT NULL, "source_ref" varchar(500) NOT NULL, "source_notes" text NOT NULL, "fen" varchar(100) NOT NULL, "canonical_fen" varchar(100) NOT NULL UNIQUE, "placement" varchar(80) NOT NULL, "side_to_move" varchar(1) NOT NULL, "material" varchar(40) NOT NULL, "piece_squares" varchar(200) NOT NULL, "title" varchar(200) NOT NULL, "description" text NOT NULL, "notes" text NOT NULL, "solution_text" text NOT NULL, "difficulty_auto" smallint unsigned NULL CHECK ("difficulty_auto" >= 0), "difficulty_override" smallint unsigned NULL CHECK ("difficulty_override" >= 0), "difficulty" smallint unsigned NULL CHECK ("difficulty" >= 0), "spectrum" varchar(12) NOT NULL, "orientation" varchar(6) NOT NULL, "has_solution" bool NOT NULL, "game_ply" integer unsigned NULL CHECK ("game_ply" >= 0), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "book_id" bigint NULL REFERENCES "sources_book" ("id") DEFERRABLE INITIALLY DEFERRED, "game_id" bigint NULL REFERENCES "positions_game" ("id") DEFERRABLE INITIALLY DEFERRED, "website_id" bigint NULL REFERENCES "sources_website" ("id") DEFERRABLE INITIALLY DEFERRED, "deleted_at" datetime NULL, "auto_tagged_at" datetime NULL, "diagram" bool NOT NULL);
CREATE TABLE "positions_variationnode" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "sort_order" smallint unsigned NOT NULL CHECK ("sort_order" >= 0), "ply" integer unsigned NOT NULL CHECK ("ply" >= 0), "uci" varchar(6) NOT NULL, "san" varchar(12) NOT NULL, "fen_before" varchar(100) NOT NULL, "fen_after" varchar(100) NOT NULL, "comment" text NOT NULL, "starting_comment" text NOT NULL, "nags" text NOT NULL CHECK ((JSON_VALID("nags") OR "nags" IS NULL)), "game_id" bigint NULL REFERENCES "positions_game" ("id") DEFERRABLE INITIALLY DEFERRED, "position_id" bigint NULL REFERENCES "positions_position" ("id") DEFERRABLE INITIALLY DEFERRED, "shapes" text NOT NULL CHECK ((JSON_VALID("shapes") OR "shapes" IS NULL)), "color" varchar(9) NOT NULL, "quality" varchar(8) NOT NULL, "parent_id" bigint NULL REFERENCES "positions_variationnode" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "variationnode_single_owner" CHECK ((("game_id" IS NULL AND "position_id" IS NOT NULL) OR ("game_id" IS NOT NULL AND "position_id" IS NULL))));
CREATE TABLE "positions_tagfield" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "key" varchar(40) NOT NULL UNIQUE, "name" varchar(80) NOT NULL, "name_en" varchar(80) NOT NULL, "selection" varchar(6) NOT NULL, "applies_to_moves" bool NOT NULL, "color" varchar(20) NOT NULL, "spectrum_hint" varchar(12) NOT NULL, "description" text NOT NULL, "order" smallint unsigned NOT NULL CHECK ("order" >= 0), "applies_to_positions" bool NOT NULL);
CREATE TABLE "positions_tag" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "slug" varchar(100) NOT NULL UNIQUE, "base_difficulty" smallint unsigned NOT NULL CHECK ("base_difficulty" >= 0), "weight" real NOT NULL, "description" text NOT NULL, "field_id" bigint NOT NULL REFERENCES "positions_tagfield" ("id") DEFERRABLE INITIALLY DEFERRED, "name_en" varchar(100) NOT NULL, "aliases" text NOT NULL CHECK ((JSON_VALID("aliases") OR "aliases" IS NULL)), "order" smallint unsigned NOT NULL CHECK ("order" >= 0), "task" varchar(120) NOT NULL, "task_en" varchar(120) NOT NULL, "search_text" text NOT NULL, "analysis_weight" real NOT NULL, "parent_id" bigint NULL REFERENCES "positions_tag" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "positions_positiontag" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "source" varchar(6) NOT NULL, "evidence" varchar(200) NOT NULL, "created_at" datetime NOT NULL, "position_id" bigint NOT NULL REFERENCES "positions_position" ("id") DEFERRABLE INITIALLY DEFERRED, "tag_id" bigint NOT NULL REFERENCES "positions_tag" ("id") DEFERRABLE INITIALLY DEFERRED, "detector" varchar(40) NOT NULL, "confidence" real NULL, CONSTRAINT "unique_tag_per_position" UNIQUE ("position_id", "tag_id"));
CREATE TABLE "positions_nodetag" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "source" varchar(6) NOT NULL, "detector" varchar(40) NOT NULL, "evidence" varchar(200) NOT NULL, "confidence" real NULL, "created_at" datetime NOT NULL, "node_id" bigint NOT NULL REFERENCES "positions_variationnode" ("id") DEFERRABLE INITIALLY DEFERRED, "tag_id" bigint NOT NULL REFERENCES "positions_tag" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_tag_per_node" UNIQUE ("node_id", "tag_id"));
CREATE TABLE "positions_tagsuggestion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "evidence" varchar(200) NOT NULL, "status" varchar(10) NOT NULL, "created_at" datetime NOT NULL, "position_id" bigint NOT NULL REFERENCES "positions_position" ("id") DEFERRABLE INITIALLY DEFERRED, "tag_id" bigint NOT NULL REFERENCES "positions_tag" ("id") DEFERRABLE INITIALLY DEFERRED, "detector" varchar(40) NOT NULL, CONSTRAINT "unique_suggestion_per_position" UNIQUE ("position_id", "tag_id"));
CREATE TABLE "boards_board" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "description" text NOT NULL, "color" varchar(20) NOT NULL, "archived" bool NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE "boards_column" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "color" varchar(20) NOT NULL, "board_id" bigint NOT NULL REFERENCES "boards_board" ("id") DEFERRABLE INITIALLY DEFERRED, "weight" smallint unsigned NOT NULL CHECK ("weight" >= 0));
CREATE TABLE "boards_positioninboard" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "order" integer unsigned NOT NULL CHECK ("order" >= 0), "note" varchar(300) NOT NULL, "added_at" datetime NOT NULL, "board_id" bigint NOT NULL REFERENCES "boards_board" ("id") DEFERRABLE INITIALLY DEFERRED, "column_id" bigint NOT NULL REFERENCES "boards_column" ("id") DEFERRABLE INITIALLY DEFERRED, "position_id" bigint NOT NULL REFERENCES "positions_position" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_position_per_board" UNIQUE ("board_id", "position_id"));
CREATE TABLE "training_trainingpuzzle" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "active" bool NOT NULL, "solution" text NOT NULL CHECK ((JSON_VALID("solution") OR "solution" IS NULL)), "marked_at" datetime NOT NULL, "created_at" datetime NOT NULL, "node_id" bigint NOT NULL UNIQUE REFERENCES "positions_variationnode" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "training_trainingcard" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "state" varchar(10) NOT NULL, "due" datetime NOT NULL, "interval_days" real NOT NULL, "ease" real NOT NULL, "step" smallint unsigned NOT NULL CHECK ("step" >= 0), "reps" integer unsigned NOT NULL CHECK ("reps" >= 0), "lapses" integer unsigned NOT NULL CHECK ("lapses" >= 0), "success_streak" integer unsigned NOT NULL CHECK ("success_streak" >= 0), "attempts" integer unsigned NOT NULL CHECK ("attempts" >= 0), "successes" integer unsigned NOT NULL CHECK ("successes" >= 0), "total_ms" bigint NOT NULL, "best_ms" integer unsigned NULL CHECK ("best_ms" >= 0), "last_result" bool NULL, "last_seen" datetime NULL, "puzzle_id" bigint NOT NULL REFERENCES "training_trainingpuzzle" ("id") DEFERRABLE INITIALLY DEFERRED, "line" varchar(200) NOT NULL, "in_solution" bool NOT NULL, "created_at" datetime NOT NULL, CONSTRAINT "one_card_per_puzzle_line" UNIQUE ("puzzle_id", "line"));
CREATE TABLE "training_trainingsession" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "mode" varchar(6) NOT NULL, "minutes" smallint unsigned NULL CHECK ("minutes" >= 0), "options" text NOT NULL CHECK ((JSON_VALID("options") OR "options" IS NULL)), "started_at" datetime NOT NULL, "ended_at" datetime NULL, "solved" integer unsigned NOT NULL CHECK ("solved" >= 0), "failed" integer unsigned NOT NULL CHECK ("failed" >= 0), "best_combo" integer unsigned NOT NULL CHECK ("best_combo" >= 0), "streak" integer unsigned NOT NULL CHECK ("streak" >= 0), "duration_s" integer unsigned NULL CHECK ("duration_s" >= 0), "lives" smallint unsigned NOT NULL CHECK ("lives" >= 0));
CREATE TABLE "training_trainingattempt" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "at" datetime NOT NULL, "success" bool NOT NULL, "ms" integer unsigned NOT NULL CHECK ("ms" >= 0), "wrong_move" varchar(8) NOT NULL, "mode" varchar(6) NOT NULL, "visual" varchar(12) NOT NULL, "first_move_only" bool NOT NULL, "counted" bool NOT NULL, "state_before" varchar(10) NOT NULL, "interval_after" real NOT NULL, "card_id" bigint NOT NULL REFERENCES "training_trainingcard" ("id") DEFERRABLE INITIALLY DEFERRED, "session_id" bigint NULL REFERENCES "training_trainingsession" ("id") DEFERRABLE INITIALLY DEFERRED, "due_before" datetime NULL, "flipped" bool NULL, "interval_before" real NULL, "mirrored" bool NULL, "solved_as" varchar(1) NOT NULL);
CREATE TABLE "core_activityevent" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "kind" varchar(12) NOT NULL, "points" smallint NOT NULL, "created_at" datetime NOT NULL, "label" varchar(200) NOT NULL, "board_id" bigint NULL REFERENCES "boards_board" ("id") DEFERRABLE INITIALLY DEFERRED, "from_column_id" bigint NULL REFERENCES "boards_column" ("id") DEFERRABLE INITIALLY DEFERRED, "position_id" bigint NULL REFERENCES "positions_position" ("id") DEFERRABLE INITIALLY DEFERRED, "to_column_id" bigint NULL REFERENCES "boards_column" ("id") DEFERRABLE INITIALLY DEFERRED);
